class WisprError(
    RootModel[
        ErrorResolutionAmbiguous
        | ErrorResolutionNotFound
        | ErrorResolutionTimeout
        | ErrorMemoryVersionMismatch
        | ErrorMemorySnapshotUnavailable
        | ErrorActionConfirmationRequired
        | ErrorActionTargetStale
        | ErrorActionDispatchFailed
        | ErrorSessionClosed
        | ErrorConstraintUnsatisfiable
        | ErrorSchemaConfidenceTooLow
        | ErrorReferenceTargetMissing
        | ErrorUniquenessExhausted
        | ErrorMaterializerUnavailable
        | ErrorMaterializationFailed
        | ErrorSeedingForbidden
        | ErrorDriftApprovalRequired
        | ErrorUnauthorized
        | ErrorForbidden
        | ErrorRateLimited
        | ErrorValidationFailed
        | ErrorInternal
    ]
):
    root: Annotated[
        ErrorResolutionAmbiguous
        | ErrorResolutionNotFound
        | ErrorResolutionTimeout
        | ErrorMemoryVersionMismatch
        | ErrorMemorySnapshotUnavailable
        | ErrorActionConfirmationRequired
        | ErrorActionTargetStale
        | ErrorActionDispatchFailed
        | ErrorSessionClosed
        | ErrorConstraintUnsatisfiable
        | ErrorSchemaConfidenceTooLow
        | ErrorReferenceTargetMissing
        | ErrorUniquenessExhausted
        | ErrorMaterializerUnavailable
        | ErrorMaterializationFailed
        | ErrorSeedingForbidden
        | ErrorDriftApprovalRequired
        | ErrorUnauthorized
        | ErrorForbidden
        | ErrorRateLimited
        | ErrorValidationFailed
        | ErrorInternal,
        Field(
            description="Every failure that can cross a process boundary, discriminated on `code`."
        ),
    ]


class WisprErrorCode(StrEnum):
    """
    Discriminator of the WisprError union.
    """

    RESOLUTION_AMBIGUOUS = "resolution_ambiguous"
    RESOLUTION_NOT_FOUND = "resolution_not_found"
    RESOLUTION_TIMEOUT = "resolution_timeout"
    MEMORY_VERSION_MISMATCH = "memory_version_mismatch"
    MEMORY_SNAPSHOT_UNAVAILABLE = "memory_snapshot_unavailable"
    ACTION_CONFIRMATION_REQUIRED = "action_confirmation_required"
    ACTION_TARGET_STALE = "action_target_stale"
    ACTION_DISPATCH_FAILED = "action_dispatch_failed"
    SESSION_CLOSED = "session_closed"
    CONSTRAINT_UNSATISFIABLE = "constraint_unsatisfiable"
    SCHEMA_CONFIDENCE_TOO_LOW = "schema_confidence_too_low"
    REFERENCE_TARGET_MISSING = "reference_target_missing"
    UNIQUENESS_EXHAUSTED = "uniqueness_exhausted"
    MATERIALIZER_UNAVAILABLE = "materializer_unavailable"
    MATERIALIZATION_FAILED = "materialization_failed"
    SEEDING_FORBIDDEN = "seeding_forbidden"
    DRIFT_APPROVAL_REQUIRED = "drift_approval_required"
    UNAUTHORIZED = "unauthorized"
    FORBIDDEN = "forbidden"
    RATE_LIMITED = "rate_limited"
    VALIDATION_FAILED = "validation_failed"
    INTERNAL = "internal"


